    background-color: rgba(0,0,0,0.9);
}
.custom-lightbox .lightbox-content {
    margin: auto;
    display: block;
    max-width: 80%;
    max-height: 80vh;
    object-fit: contain;
    background: #fff;
    padding: 20px;
    border-radius: 10px;
    opacity: 1 !important;
    visibility: visible !important;
}
.lightbox-close {
    position: absolute;
    top: 30px;
