    color: #f1f1f1 !important;
    font-size: 50px !important;
    font-weight: bold;
    cursor: pointer;
    z-index: 1000000 !important;
    pointer-events: auto !important;
}
</style>
<script>
function openLightbox(imgSrc) {
    var img = document.getElementById("lightbox-img");
    var lb = document.getElementById("custom-lightbox");
    if(img && lb) {
        img.src = imgSrc;
        lb.style.cssText = "display: block !important; opacity: 1 !important; visibility: visible !important; position: fixed !important; z-index: 9999999 !important; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.9);";
    } else {
        alert("Lightbox elements not found!");
    }
}
function closeLightbox() {
    var lb = document.getElementById("custom-lightbox");
    if(lb) {
        lb.style.cssText = "display: none !important;";
    }
}
</script>

		
